exploreUrl:
@js:
var items = [];
function makeWenkuPath(overrides) {
  var cfg = ['lastupdate', '0', '0', '0', '0', '0', '0', '0', '{{page}}', '0'];
  var keys = ['order', 'tagid', 'isfull', 'anime', 'rgroupid', 'sortid', 'typeid', 'words', 'page', 'update'];
  for (var n = 0; n < keys.length; n++) {
    if (overrides[keys[n]] != null) { cfg[n] = overrides[keys[n]]; }
  }
  return source.bookSourceUrl + '/wenku/' + cfg.join('_') + '.html';
}
var page = org.jsoup.Jsoup.parse(java.ajax(source.bookSourceUrl + '/wenku/'));
var groups = page.select('ul#filters li.sort-li');
var idx = 0;
while (idx < groups.size()) {
  var grp = groups.get(idx);
  var head = grp.select('h3.sort-li-title').first();
  var label = head != null ? head.text() : '';
  items.push({title: '>> ' + label + ' <<', url: '', style: {layout_flexGrow: 1, layout_flexBasisPercent: 1}});
  var opts = grp.select('a.btn-tag.jsTag');
  var j = 0;
  while (j < opts.size()) {
    var opt = opts.get(j);
    var ov = {};
    ov[opt.attr('data-filter-type')] = opt.attr('data-filter-value');
    items.push({title: opt.text(), url: makeWenkuPath(ov), style: {layout_flexGrow: 1}});
    j++;
  }
  idx++;
}
JSON.stringify(items);

ruleContent.content:
#acontent@html@js:
var html = result;
// 1. 将 data-src 转换为 src
html = html.replace(/data-src="([^"]+)"/g, 'src="$1"');
// 2. 去掉无用的占位图 src（防止加载失败）
html = html.replace(/src="\/images\/sloading\.svg"/g, '');
// 3. 让隐藏的图片显示出来
html = html.replace(/style="display:none;"/g, '');
html;

